using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Shares users after pressing a keyboardButtonTypeRequestUsers button with the bot
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ShareUsersWithBotAsync(long chatId = default, long messageId = default, int buttonId = default, long[] sharedUserIds = default, bool onlyCheck = default)
    {

           using var activity =  StartCallActivity("ShareUsersWithBotAsync", typeof(ShareUsersWithBot).FullName ?? "ShareUsersWithBotAsync");

           try
           {
             return client.ShareUsersWithBotAsync(chatId, messageId, buttonId, sharedUserIds, onlyCheck);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
